  'admin.oauth.intro': 'WeChat ಸ್ಕ್ಯಾನ್ ಕೋಡ್ ಲಾಗಿನ್ ಎಲ್ಲಾ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ಗಳಲ್ಲಿ ಲಭ್ಯವಿದೆ (FEATURE_WECHAT_LOGIN + AppID/Secret; ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ಮುಚ್ಚಲಾಗಿದೆ, ಉತ್ಪಾದನೆಗೆ ಮಾತ್ರ ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ - ತೆರೆದ ವೇದಿಕೆಯು ಕೇವಲ ಒಂದು ಕಾಲ್‌ಬ್ಯಾಕ್ ಡೊಮೇನ್ ಹೆಸರನ್ನು ಅನುಮತಿಸುತ್ತದೆ). DingTalk ಅನ್ನು ಶಾಲೆಯ ಮೂಲಕ ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾಗಿದೆ (FEATURE_DINGTALK_LOGIN + AppKey/AppSecret; ಡೀಫಾಲ್ಟ್ ಆಗಿ ಆಫ್ ಮಾಡಲಾಗಿದೆ).',
  'admin.oauth.officialDocsHint': 'ಪ್ರಕ್ರಿಯೆಯು ಅಧಿಕೃತ ದಾಖಲಾತಿಯೊಂದಿಗೆ ಸ್ಥಿರವಾಗಿದೆ: ಟೋಕನ್ ವಿನಿಮಯಕ್ಕಾಗಿ WeChat WxLogin + ಕೋಡ್ ಅನ್ನು ಬಳಸುತ್ತದೆ; DingTalk OAuth 2.0 DTFrameLogin + authCode ನೇರವಾಗಿ userAccessToken ಗಾಗಿ ವಿನಿಮಯಗೊಳ್ಳುತ್ತದೆ (ಲೆಗಸಿ oapi.dingtalk.com ಅನ್ನು ಬಳಸಬೇಡಿ).',
  'admin.oauth.wechatToggle': 'ಲಾಗ್ ಇನ್ ಮಾಡಲು WeChat ಸ್ಕ್ಯಾನ್ ಕೋಡ್',
  'admin.oauth.wechatHint': 'ಸರ್ವರ್ .env ನಲ್ಲಿ ಮಾತ್ರ ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾಗಿದೆ. ಉತ್ಪಾದನಾ ಪರಿಸರವನ್ನು ಹೊಂದಿಸುತ್ತದೆ FEATURE_WECHAT_LOGIN=ನಿಜ. ಶಿಕ್ಷಕರು ಮೊದಲು ಖಾತೆ ಬೈಂಡಿಂಗ್‌ನಲ್ಲಿ WeChat ಅನ್ನು ಸಂಯೋಜಿಸಬೇಕು ಮತ್ತು ಲಾಗ್ ಇನ್ ಮಾಡಲು QR ಕೋಡ್ ಅನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಬೇಕು.',
