  'admin.oauth.schoolItChecklist': 'DingTalk IT ಪರಿಶೀಲನಾಪಟ್ಟಿ:\n1. "ಮೂರನೇ ಪಕ್ಷದ ವೆಬ್‌ಸೈಟ್‌ಗಳಿಗೆ ಲಾಗ್ ಇನ್ ಮಾಡಿ/ಲಾಗ್ ಇನ್ ಮಾಡಲು QR ಕೋಡ್ ಅನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಿ" ಸಕ್ರಿಯಗೊಳಿಸಿ\n2. "DingTalk ಲಾಗಿನ್ ಮತ್ತು ಹಂಚಿಕೆ" ಕಾನ್ಫಿಗರೇಶನ್‌ನಲ್ಲಿ DingTalk ಕಾಲ್‌ಬ್ಯಾಕ್ URL ಅನ್ನು ನಮೂದಿಸಿ (ನಿಖರವಾಗಿ ಒಂದೇ ಆಗಿರಬೇಕು)\n3. ವೈಯಕ್ತಿಕ ಅನುಮತಿಗಳಿಗಾಗಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಿ: ಅನುಮತಿ-open_app_api_base, Contact.User.Read\n4. MindGraph ನಿರ್ವಾಹಕರಿಗೆ AppKey, AppSecret, CorpId (ಐಚ್ಛಿಕ) ಒದಗಿಸಿ',
