  'admin.mindbot.standaloneDifySchoolHint': 'ಹೆಚ್ಚಿನ ಶಾಲೆಗಳಿಗೆ, ದಯವಿಟ್ಟು ಸಂಪಾದಿಸಿ ಶಾಲೆಯ ಪಾಪ್-ಅಪ್ ವಿಂಡೋದಲ್ಲಿ ಮೈಂಡ್‌ಮೇಟ್ ದೃಢೀಕರಣದಲ್ಲಿ Dify ಅನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಿ; ಶಾಲೆಯನ್ನು ಉಳಿಸುವಾಗ, ಅದನ್ನು ಶಾಲೆಯ ಎಲ್ಲಾ ರೋಬೋಟ್‌ಗಳಿಗೆ ಸಿಂಕ್ರೊನೈಸ್ ಮಾಡಲಾಗುತ್ತದೆ. ಇಲ್ಲಿ ರೋಬೋಟ್‌ನಿಂದ ಪ್ರತ್ಯೇಕ ಕಾನ್ಫಿಗರೇಶನ್ ಅನ್ನು ವಿಶೇಷ ಸಂದರ್ಭಗಳಲ್ಲಿ ಮಾತ್ರ ಬಳಸಲಾಗುತ್ತದೆ ಮತ್ತು ಶಾಲೆಯನ್ನು ಉಳಿಸುವಾಗ ತಿದ್ದಿ ಬರೆಯಬಹುದು.',
