  'admin.mindbot.logTabHint': 'ನಮ್ಮ ಶಾಲೆಯ ಮೂಲ ಮೈಂಡ್‌ಬಾಟ್ ಬಳಕೆಯ ದಾಖಲೆ (ಮೇಲ್ಭಾಗದಲ್ಲಿ ಹೊಸದು). ಸಂಪೂರ್ಣ ಮೆಟಾಡೇಟಾವನ್ನು ವೀಕ್ಷಿಸಲು ಸಾಲಿನ ಮೇಲೆ ಕ್ಲಿಕ್ ಮಾಡಿ. ಬಳಕೆದಾರ ಮತ್ತು ಬೋಟ್ ಸಂದೇಶ ದೇಹಗಳನ್ನು ಉಳಿಸಲಾಗಿಲ್ಲ.',
