  'admin.roleControlDescManagers': 'ಶಾಲಾ ನಿರ್ವಾಹಕರನ್ನು ನಿರ್ವಹಿಸಿ. ಶಾಲಾ ನಿರ್ವಾಹಕರು ತಮ್ಮ ಸಂಸ್ಥೆಗಾಗಿ ಶಾಲೆಯ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಅನ್ನು ಪ್ರವೇಶಿಸಬಹುದು. ಈ ಪಾತ್ರವನ್ನು ನೀಡುವ ಮೊದಲು ಬಳಕೆದಾರರು ಶಾಲೆಗೆ ಸೇರಿರಬೇಕು.',
