  'admin.schoolFeatureUsage.nameSep': ', ',
  'admin.schoolFeatureUsage.noneListed': 'ಯಾವುದೂ ಇಲ್ಲ',
  'admin.schoolFeatureUsage.bottleneckNone': 'ಈ ವರ್ಷದ ಪ್ರತಿ ವ್ಯವಹಾರ ಪ್ರಕ್ರಿಯೆಯ ಉತ್ತೀರ್ಣ ದರವು ಒಟ್ಟಾರೆ ಸ್ಥಿರವಾಗಿದೆ ಮತ್ತು LLM ಪ್ರತಿಕ್ರಿಯೆಯು ನಿಸ್ಸಂಶಯವಾಗಿ ನಿಧಾನವಾಗಿರಲಿಲ್ಲ (ಇದು ಸರಾಸರಿಗಿಂತ ಹೆಚ್ಚಾಗಿರಬೇಕು ಮತ್ತು ಈ ಮಾಡ್ಯೂಲ್‌ನ ಮಿತಿಯನ್ನು ತಲುಪಬೇಕು: ಕ್ಯಾನ್ವಾಸ್‌ಗೆ 8 ಸೆಕೆಂಡುಗಳು ಮತ್ತು ಸಂಭಾಷಣೆಗಾಗಿ 90 ಸೆಕೆಂಡುಗಳು). ಪ್ರಕ್ರಿಯೆಯ ಪಾಸ್ ದರವು ಕ್ರಿಯಾತ್ಮಕ ಘಟನೆಗಳಿಂದ ಬರುತ್ತದೆ ಮತ್ತು LLM ವೈಫಲ್ಯದ ಪ್ರಮಾಣವು ಟೋಕನ್ ಬಳಕೆಯಿಂದ ಬರುತ್ತದೆ.',
  'admin.schoolFeatureUsage.bottleneckVolume': 'ಪ್ರತಿ ಪ್ರಕ್ರಿಯೆಯ ಉತ್ತೀರ್ಣ ದರವು ಸಾಮಾನ್ಯವಾಗಿ ಹೆಚ್ಚಾಗಿರುತ್ತದೆ. ಪ್ರಸ್ತುತ ನಿರ್ಬಂಧಗಳು ಮುಖ್ಯವಾಗಿ ಬಳಕೆಯ ವಿತರಣೆ ಮತ್ತು ನಿಷ್ಕ್ರಿಯ ಮಾಡ್ಯೂಲ್‌ಗಳಿಂದ ಬರುತ್ತವೆ ({idle}), ಬದಲಿಗೆ ಪ್ರಕ್ರಿಯೆಯ ವೈಫಲ್ಯಗಳು ಅಥವಾ ನಿಧಾನತೆ.',
  'admin.schoolFeatureUsage.bottleneckSlow': 'ತೇರ್ಗಡೆ ದರವು ಒಟ್ಟಾರೆ ಸ್ಥಿರವಾಗಿದೆ. ಈ ಮಾಡ್ಯೂಲ್‌ನ ಥ್ರೆಶೋಲ್ಡ್ ಅನ್ನು ಪೂರೈಸುವ ಮಧ್ಯದ ಮೇಲಿನ LLM ಸರಾಸರಿ ಪ್ರತಿಕ್ರಿಯೆಯೊಂದಿಗೆ ಪ್ರಕ್ರಿಯೆಗಳು {slow}.',
  'admin.schoolFeatureUsage.bottleneckPass': 'ಕಡಿಮೆ ಪಾಸ್ ದರವನ್ನು ಹೊಂದಿರುವ ಪ್ರಕ್ರಿಯೆಯು {lowest} ಆಗಿದೆ; ಬಿಗಿಯಾದ ಲೋಡ್ ಮೌಲ್ಯಮಾಪನದೊಂದಿಗೆ ಪ್ರಕ್ರಿಯೆಯು {tense} ಆಗಿದೆ. ಪಾಸ್ ದರವು ಕ್ರಿಯಾತ್ಮಕ ಈವೆಂಟ್‌ಗಳಿಂದ ಬಂದಿದೆ, ದಯವಿಟ್ಟು ಅದನ್ನು ಬಳಕೆಯ ಆಧಾರದ ಮೇಲೆ ಅರ್ಥೈಸಿಕೊಳ್ಳಿ.',
  'admin.schoolFeatureUsage.bottleneckPassSlow': 'ಕಡಿಮೆ ಪಾಸ್ ದರದೊಂದಿಗೆ ಪ್ರಕ್ರಿಯೆಯು {lowest} ಆಗಿದೆ; ಲೋಡ್ ಮೌಲ್ಯಮಾಪನವನ್ನು ಬಿಗಿಯಾಗಿ ಹೊಂದಿರುವ ಪ್ರಕ್ರಿಯೆಯು {tense} ಆಗಿದೆ; ನಿಧಾನಗತಿಯ LLM ಪ್ರತಿಕ್ರಿಯೆಯೊಂದಿಗಿನ ಪ್ರಕ್ರಿಯೆಯು (ಮಧ್ಯದ ಮೇಲೆ ಮತ್ತು ಮಾಡ್ಯೂಲ್ ಮಿತಿಯನ್ನು ತಲುಪುತ್ತದೆ) {slow} ಆಗಿದೆ.',
  'admin.schoolFeatureUsage.top5Title': '1. ಕೋರ್ ಫಂಕ್ಷನ್ ಕವರೇಜ್ ಶ್ರೇಯಾಂಕ (ಟಾಪ್ 5)',
  'admin.schoolFeatureUsage.top5Empty': 'ಈ ವರ್ಷ ಬಳಕೆದಾರರನ್ನು ಪ್ರವೇಶಿಸಲು ಯಾವುದೇ ಮಾಡ್ಯೂಲ್‌ಗಳಿಲ್ಲ.',
  'admin.schoolFeatureUsage.usageRateHint': 'ವ್ಯಾಪ್ತಿ = ವಾರ್ಷಿಕ ಸಂದರ್ಶಕರ ಸಂಖ್ಯೆ / ಪ್ರಸ್ತುತ ವಿದ್ಯಾರ್ಥಿಗಳ ಸಂಖ್ಯೆ.',
  'admin.schoolFeatureUsage.highTitle': '2. ಹೆಚ್ಚಿನ ಆವರ್ತನ ಕಾರ್ಯ ಪಟ್ಟಿ',
  'admin.schoolFeatureUsage.lowIdleTitle': '3. ಕಡಿಮೆ ಆವರ್ತನ ಮತ್ತು ದೀರ್ಘಾವಧಿಯ ಐಡಲ್ ಕಾರ್ಯಗಳ ಪಟ್ಟಿ',
  'admin.schoolFeatureUsage.lowIdleBody': 'ಕಡಿಮೆ ಆವರ್ತನ: {low}. ದೀರ್ಘಾವಧಿಯ ಐಡಲ್: {idle}. ಐಡಲ್ ಮಾಹಿತಿಯು ಶಾಲೆಯಿಂದ ಸಕ್ರಿಯಗೊಳಿಸದ ಕಾರ್ಯಗಳನ್ನು ಒಳಗೊಂಡಿರಬಹುದು.',
  'admin.schoolFeatureUsage.conclusionTitle': '4. ಕಾರ್ಯದ ಬಳಕೆಯ ಮೇಲೆ ಸಮಗ್ರ ಸಂಶೋಧನೆ ಮತ್ತು ತೀರ್ಪು',
  'admin.schoolFeatureUsage.conclusionConcentrated': 'ಬಳಕೆಯು {top} ನಲ್ಲಿ ಕೇಂದ್ರೀಕೃತವಾಗಿದೆ. ನಿಷ್ಕ್ರಿಯವಾಗಿರುವ ಅಥವಾ ಡ್ರಾಪ್ ಈವೆಂಟ್ ಅನ್ನು ರಚಿಸದ ಮಾಡ್ಯೂಲ್ {idle} ಆಗಿದೆ. ಬಳಕೆಯು ಕೆಲವು ಪ್ರಮುಖ ಕಾರ್ಯಗಳ ಮೇಲೆ ಕೇಂದ್ರೀಕೃತವಾಗಿದೆ ಮತ್ತು ನಿಷ್ಕ್ರಿಯ ಐಟಂಗಳು ನಿಷ್ಕ್ರಿಯ ಕಾರ್ಯಗಳನ್ನು ಒಳಗೊಂಡಿರಬಹುದು.',
  'admin.schoolFeatureUsage.conclusionSpread': 'ಬಳಕೆಯು ತುಲನಾತ್ಮಕವಾಗಿ ಚದುರಿಹೋಗಿದೆ, ಮತ್ತು ಉನ್ನತ ಮಾಡ್ಯೂಲ್ {top} ಆಗಿದೆ. ನಿಷ್ಕ್ರಿಯವಾಗಿರುವ ಅಥವಾ ಡ್ರಾಪ್‌ಔಟ್ ಈವೆಂಟ್ ಅನ್ನು ರಚಿಸದ ಮಾಡ್ಯೂಲ್ {idle} ಆಗಿದೆ. ಐಡಲ್ ಐಟಂಗಳು ಸಕ್ರಿಯಗೊಳಿಸದ ಕಾರ್ಯಗಳನ್ನು ಹೊಂದಿರಬಹುದು.',
