  'admin.schoolModal.mindbotIntro': 'ನಮ್ಮ ಶಾಲೆಯ DingTalk ರೋಬೋಟ್ ಅನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಿ. ಶಾಲೆಯ ಡಿಫೈ ಇನ್ ಮೈಂಡ್‌ಮೇಟ್ ದೃಢೀಕರಣವನ್ನು ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ; ಬಹು ರೋಬೋಟ್‌ಗಳು ವಿಭಿನ್ನ Dify ಅನ್ನು ಬಳಸಬೇಕಾದರೆ, ನೀವು AI ಕಾರ್ಡ್ ಟೆಂಪ್ಲೇಟ್ ಅಡಿಯಲ್ಲಿ "ಕಸ್ಟಮೈಸ್ ಮಾಡಿದ Dify ಸೆಟ್ಟಿಂಗ್‌ಗಳು" ಅನ್ನು ಆಯ್ಕೆ ಮಾಡಬಹುದು.',
