  'admin.schoolDifyDualServerHint': 'ಪ್ರತಿ ಶಾಲೆಗೆ ಎರಡು ಡಿಫೈ ಸರ್ವರ್‌ಗಳನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಿ. ಸಕ್ರಿಯ ಸರ್ವರ್ ನೈಜ-ಸಮಯದ MindMate ಸಂಭಾಷಣೆಗಳನ್ನು ನಿರ್ವಹಿಸುತ್ತದೆ; ಸ್ವಯಂಚಾಲಿತ ಸ್ವಿಚಿಂಗ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ, ಸಕ್ರಿಯ ಸರ್ವರ್ ಲಭ್ಯವಿಲ್ಲದಿದ್ದಾಗ ಟ್ರಾಫಿಕ್ ಅನ್ನು ಬ್ಯಾಕಪ್ ಸರ್ವರ್‌ಗೆ ಬದಲಾಯಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಚೇತರಿಕೆಯ ನಂತರ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ.',
