  'admin.mindmateExport.description': 'ಮೈಂಡ್‌ಮೇಟ್ (ಡಿಫೈ) ಸಂಭಾಷಣೆಯ ಪ್ರತಿಗಳನ್ನು ಒಬ್ಬ ಬಳಕೆದಾರ, ಬಹು ಬಳಕೆದಾರರು ಅಥವಾ ಇಡೀ ಶಾಲೆಗೆ ಸಮಯದ ವ್ಯಾಪ್ತಿಯ ಮೂಲಕ ವೀಕ್ಷಿಸಿ ಮತ್ತು ರಫ್ತು ಮಾಡಿ. ಎರಡೂ ಡಿಫೈ ಸರ್ವರ್‌ಗಳಲ್ಲಿ ದಾಖಲೆಗಳನ್ನು ವಿಲೀನಗೊಳಿಸಲಾಗಿದೆ.',
