  'admin.shareInviteMessage': '{orgName}: ಮೈಂಡ್ ಥಿಂಕಿಂಗ್ ಬೋಧನೆ ಮತ್ತು ಸಂಶೋಧನಾ ಏಜೆಂಟ್ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅನ್ನು ಅನುಭವಿಸಲು ಸುಸ್ವಾಗತ! \nಬೀಜಿಂಗ್ ನಾರ್ಮಲ್ ವಿಶ್ವವಿದ್ಯಾನಿಲಯದ ಚಿಂತನೆಯ ತರಬೇತಿ ಕೇಂದ್ರವು ಸಂಶೋಧನೆ ಮತ್ತು ಅಭಿವೃದ್ಧಿಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತದೆ ಮತ್ತು ನೂರಕ್ಕೂ ಹೆಚ್ಚು ಚಿಂತನೆಯ ಅಭಿವೃದ್ಧಿ ಮೈತ್ರಿ ಶಾಲೆಗಳಿಂದ ಸಹ-ನಿರ್ಮಿಸಲಾಗಿದೆ. ಜಂಟಿ ಸಂಶೋಧನೆಯಲ್ಲಿ ನಿಮ್ಮ ಗೆಳೆಯರೊಂದಿಗೆ ಸೇರಲು ಮತ್ತು AI ಯುಗದಲ್ಲಿ ನಿಮ್ಮ ಆಲೋಚನಾ ಸಾಮರ್ಥ್ಯವನ್ನು ಸುಧಾರಿಸಲು ನಿಮ್ಮನ್ನು ಆಹ್ವಾನಿಸಲಾಗಿದೆ! \nವಿಧಾನ: ಕಂಪ್ಯೂಟರ್ ಅಥವಾ ಮೊಬೈಲ್ ಫೋನ್ ತೆರೆಯಿರಿ, ಮೊದಲ ಬಾರಿಗೆ ನೋಂದಣಿಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಲು ಮೊಬೈಲ್ ಫೋನ್ ಸಂಖ್ಯೆ + ಆಹ್ವಾನ ಕೋಡ್ ಬಳಸಿ ಮತ್ತು ನಂತರ ಮೊಬೈಲ್ ಫೋನ್ ಪರಿಶೀಲನೆ ಕೋಡ್‌ನೊಂದಿಗೆ ಲಾಗ್ ಇನ್ ಮಾಡಿ. \nವೆಬ್‌ಸೈಟ್: {siteUrl}\nಸಂಸ್ಥೆ-ನಿರ್ದಿಷ್ಟ ಆಹ್ವಾನ ಕೋಡ್: {code}',
